<script lang="ts">
 import {onMount} from 'svelte';
 import Challenge from '$lib/Challenge.svelte';
 import type {Run,Scenario,Session,Challenge as Payout} from '$lib/types';
 let view=$state('challenge'),scenario=$state('lost_confirmation'),scenarios=$state<Scenario[]>([]),runs=$state<Run[]>([]),payouts=$state<Payout[]>([]),run=$state<Run|null>(null);
 let loading=$state(true),starting=$state(false),busy=$state(false),error=$state(''),authRequired=$state(false),token=$state(''),copied=$state(false),session=$state<Session|null>(null),creatingSession=$state(false),refreshing=$state(false);
 let selected=$derived(scenarios.find(s=>s.id===scenario));
 let running=$derived(run?.status==='funding'||run?.status==='running');
 let proxyURL=$derived(session&&typeof window!=='undefined'?`${window.location.origin}/horizon/${session.id}/`:'');
 let short=(s:string)=>`${s.slice(0,8)}…${s.slice(-6)}`;
 let date=(s:string)=>new Intl.DateTimeFormat(undefined,{dateStyle:'medium',timeStyle:'short'}).format(new Date(s));
 let time=(s:string)=>new Intl.DateTimeFormat(undefined,{hour:'2-digit',minute:'2-digit',second:'2-digit'}).format(new Date(s));
 let amount=(s:string)=>new Intl.NumberFormat(undefined,{maximumFractionDigits:7}).format(Number(s));
 async function api(path:string,init:RequestInit={}){
  const response=await fetch(path,{...init,headers:{'Content-Type':'application/json',...(token?{Authorization:`Bearer ${token}`}:{})}});
  const data=await response.json();if(!response.ok)throw new Error(data.error||`Request failed (${response.status}). Try again.`);return data;
 }
 function syncURL(){const u=new URL(window.location.href);u.searchParams.set('view',view);u.searchParams.set('scenario',scenario);if(run)u.searchParams.set('run',run.id);else u.searchParams.delete('run');window.history.replaceState({},'',u);}
 async function refresh(){const data=await api('/api/runs');runs=data.runs;busy=data.busy;if(view==='history'){payouts=(await api('/api/challenges')).challenges;}const id=new URL(window.location.href).searchParams.get('run');if(id){run=runs.find(r=>r.id===id)||await api(`/api/runs/${id}`);}}
 async function load(){error='';loading=true;try{const config=await api('/api/config');scenarios=config.scenarios;if(!scenarios.some(s=>s.id===scenario))scenario='lost_confirmation';authRequired=config.auth_required;busy=config.busy;if(!authRequired||token)await refresh();}catch(e){error=(e as Error).message;}finally{loading=false;}}
 onMount(()=>{
  const u=new URL(window.location.href);view=['challenge','lab','history','integrate'].includes(u.searchParams.get('view')||'')?u.searchParams.get('view')!:'challenge';scenario=u.searchParams.get('scenario')||'lost_confirmation';token=sessionStorage.getItem('ledgerdrill-token')||'';load();
  const poll=setInterval(async()=>{if((!authRequired||token)&&document.visibilityState==='visible'){try{await refresh();}catch(e){error=(e as Error).message;}}},2500);
  return ()=>clearInterval(poll);
 });
 async function unlock(){sessionStorage.setItem('ledgerdrill-token',token);await load();}
 async function start(){starting=true;error='';try{run=await api('/api/runs',{method:'POST',body:JSON.stringify({scenario})});busy=true;view='lab';syncURL();await refresh();}catch(e){error=(e as Error).message;}finally{starting=false;}}
 async function exportReport(){if(!run)return;try{const data=await api(`/api/runs/${run.id}/report`);const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`ledgerdrill-${run.id}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){error=(e as Error).message;}}
 async function newSession(){creatingSession=true;error='';try{const data=await api('/api/sessions',{method:'POST',body:JSON.stringify({scenario})});session=data.session;sessionStorage.setItem('ledgerdrill-proxy-session',session!.id);}catch(e){error=(e as Error).message;}finally{creatingSession=false;}}
 async function refreshSession(){const id=session?.id||sessionStorage.getItem('ledgerdrill-proxy-session');if(!id){error='No saved proxy session in this tab. Create one above.';return;}refreshing=true;error='';try{session=await api(`/api/sessions/${id}`);}catch(e){error=(e as Error).message;}finally{refreshing=false;}}
 async function copy(text:string){try{await navigator.clipboard.writeText(text);copied=true;setTimeout(()=>copied=false,1800);}catch{error='Could not copy automatically. Select the proxy URL and copy it manually.';}}
</script>

<svelte:head><title>LedgerDrill — Test the payment you can’t see</title><meta name="description" content="Inject connection failures into real Stellar testnet payments. Compare retries, inspect ledger evidence, and catch duplicate payouts."/></svelte:head>
<a class="skip" href="#main">Skip to content</a>
<div class="app-shell" data-sveltekit-reload>
 <header class="topbar">
  <a class="brand" href="/" aria-label="LedgerDrill home"><svg viewBox="0 0 32 32" width="32" height="32" aria-hidden="true"><path d="M4 5h8v22H4zM15 5h13v6H15zM15 14h9v5h-9zM15 22h13v5H15z" fill="currentColor"/></svg><span translate="no">LedgerDrill</span></a>
  <nav aria-label="Main navigation"><a class:active={view==='challenge'} aria-current={view==='challenge'?'page':undefined} href="?view=challenge">Payout challenge</a><a class:active={view==='lab'} aria-current={view==='lab'?'page':undefined} href="?view=lab">Failure lab</a><a class:active={view==='history'} aria-current={view==='history'?'page':undefined} href="?view=history">Run history</a><a class:active={view==='integrate'} aria-current={view==='integrate'?'page':undefined} href="?view=integrate">Test your app</a></nav>
  <span class="network"><span class="dot"></span>Stellar testnet</span>
 </header>
 <main id="main">
  {#if authRequired}<form class="access" onsubmit={(e)=>{e.preventDefault();unlock();}}><label for="token">Instance access token</label><input id="token" name="token" type="password" autocomplete="current-password" bind:value={token} placeholder="Enter the configured token…"/><button class="button secondary" type="submit">Unlock instance</button></form>{/if}
  {#if error}<div class="error-message" role="alert">{error}<button class="text-button" onclick={()=>{error='';}}>Dismiss</button></div>{/if}
  {#if view==='challenge'}
   <Challenge request={api} {busy} locked={loading||(authRequired&&!token)}/>
  {:else if view==='lab'}
   <div class="intro"><div><h1>Test the payment<br/>you can’t see.</h1><p>A timeout can hide a successful payment. Break the connection,<br class="desktop-break"/> compare two recovery strategies, and see what actually settled.</p></div><div class="scope-note"><span class="mono">LIVE NETWORK / CONTROLLED FAULTS</span><p>Real testnet transactions.<br/>No real funds. No private keys needed.</p></div></div>
   <div class="lab-layout">
    <aside class="controls" aria-labelledby="controls-title">
     <h2 id="controls-title">Choose the failure</h2><p class="muted">One fault. Two reference clients. The same payment intent.</p>
     <fieldset><legend class="sr-only">Fault scenario</legend>{#each scenarios as s}<label class="scenario" class:selected={scenario===s.id}><input type="radio" name="scenario" value={s.id} bind:group={scenario} onchange={()=>syncURL()}/><span><strong>{s.name}</strong><span>{s.description}</span></span></label>{/each}</fieldset>
     {#if loading}<p role="status">Loading scenarios…</p>{/if}
     <dl class="parameters"><div><dt>Payment</dt><dd>1 XLM per intent</dd></div><div><dt>Accounts</dt><dd>Fresh, Friendbot-funded</dd></div><div><dt>Network</dt><dd>Stellar testnet only</dd></div></dl>
     <button class="button primary" disabled={starting||busy||loading||(authRequired&&!token)} onclick={start}>{starting?'Starting comparison…':busy?'Comparison running…':'Run live comparison'}<svg width="18" height="18" viewBox="0 0 24 24" aria-hidden="true"><path d="M5 12h14m-6-6 6 6-6 6" fill="none" stroke="currentColor" stroke-width="1.8"/></svg></button>
     <p class="small muted">Funding and settlement can take 30–90 seconds. Each run saves its transaction evidence.</p>
     {#if selected}<div class="expectation"><h3>What to look for</h3><p>{selected.expected}</p></div>{/if}
    </aside>
    <section class="results" aria-label="Comparison results" aria-busy={running}>
     <div class="results-heading"><div><h2>{run?'Payment recovery report':'The network tells the story'}</h2><p class="muted">{run?`${date(run.created_at)} · ${scenarios.find(s=>s.id===run!.scenario)?.name||run.scenario}`:'Client responses and ledger settlement are different things.'}</p></div>{#if run}<button class="text-button" onclick={exportReport}>Export JSON <svg width="16" height="16" viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5" fill="none" stroke="currentColor" stroke-width="1.8"/></svg></button>{/if}</div>
     {#if run}
      <div class="run-status" class:fault={run.status==='failed'||run.status==='inconclusive'||run.status==='interrupted'} role="status"><span class="status-label">{run.status.replace('_',' ')}</span><span>{run.status==='funding'?'Creating and funding three fresh test accounts…':run.status==='running'?'Running both clients, then checking transactions directly with Horizon…':run.error||'Evidence checked directly against Stellar testnet.'}</span></div>
      <div class="comparison">{#each run.clients as c}<article class="client" class:naive={c.id==='naive'}>
       <div class="client-head"><h3>{c.id==='naive'?'Naïve retry':'Reconciled retry'}</h3><span class="mono">{c.id==='naive'?'REBUILD & RESEND':'RETAIN & VERIFY'}</span></div>
       <p class="client-description">{c.id==='naive'?'Treats an error as a failed payment and creates a fresh transaction.':'Keeps the original envelope, checks its hash, and retries the same transaction.'}</p>
       <dl class="measurements"><div><dt>Submission attempts</dt><dd>{c.attempts}</dd></div><div><dt>Confirmed payments</dt><dd class:duplicate={c.settlements>1}>{c.settlements}</dd></div><div><dt>Verified received</dt><dd>{amount(c.received)} <small>XLM</small></dd></div></dl>
       <div class="verdict" class:duplicate={c.settlements>1}><span class="dot"></span>{c.verdict}</div>
       <h4>Client timeline</h4>{#if c.events.length}<ol class="timeline">{#each c.events as event}<li class:fault={event.kind==='uncertain'||event.kind==='error'}><span class="event-time mono">{time(event.at)}</span><div><span class="event-kind">{event.kind}</span><p>{event.message}</p>{#if event.hash}<a class="hash mono" href={`https://stellar.expert/explorer/testnet/tx/${event.hash}`} target="_blank" rel="noreferrer">{short(event.hash)} ↗</a>{/if}</div></li>{/each}</ol>{:else}<p class="muted small">{run.status==='funding'?'Waiting for funded accounts…':'This client is waiting for its turn.'}</p>{/if}
       {#if c.transactions.length}<h4>Independent ledger evidence</h4><ul class="evidence">{#each c.transactions as tx}<li><a class="mono" href={tx.explorer} target="_blank" rel="noreferrer">{short(tx.hash)} ↗</a><span>{tx.verification_error?'Verification unavailable':tx.confirmed?(tx.successful?`Settled · ledger ${tx.ledger}`:'Included, failed'):'Not confirmed'}</span></li>{/each}</ul>{/if}
      </article>{/each}</div>
      <p class="report-note">Counts come from unique transaction hashes verified against Horizon. Repeated submissions of one envelope count as one settlement. This report covers this scenario, not every failure your app could encounter.</p>
     {:else}
      <div class="empty-diagram"><svg viewBox="0 0 620 180" role="img" aria-label="A payment passes from your app through a fault proxy to Stellar. The reply can fail even when the payment settles."><rect x="15" y="40" width="155" height="86" rx="8"/><rect class="proxy-box" x="232" y="40" width="155" height="86" rx="8"/><rect x="449" y="40" width="155" height="86" rx="8"/><text x="92" y="77">Your app</text><text class="diagram-small" x="92" y="99">signed payment</text><text x="309" y="77">Fault proxy</text><text class="diagram-small" x="309" y="99">controlled failure</text><text x="526" y="77">Stellar</text><text class="diagram-small" x="526" y="99">actual settlement</text><path class="flow" d="M170 67h62m155 0h62"/><path class="reply" d="M449 112h-62m-155 0h-62"/><path class="fault-mark" d="m194 103 14 18m0-18-14 18"/></svg><p>Same intent. Different recovery.<br/><strong>One payment—or an accidental second one?</strong></p></div>
      <div class="empty-columns"><section><h3>Naïve retry</h3><p>An error arrives. The client creates a new payment. If the original already settled, the recipient gets paid twice.</p></section><section><h3>Reconciled retry</h3><p>The client checks the original hash and retains its signed envelope. It never turns uncertainty into a new payment.</p></section></div>
      <div class="empty-bottom"><span class="mono">NO RUN SELECTED</span><p>Choose a failure and run the comparison.<br/>The timelines will fill with real transaction evidence.</p></div>
     {/if}
    </section>
   </div>
  {:else if view==='history'}
   <div class="intro"><div><h1>Every run leaves evidence.</h1><p>Open a saved comparison, inspect the transactions, or export its report.</p></div></div>
   {#if payouts.length}<section class="saved-payouts"><h2>Your payout challenges</h2>{#each payouts as p}<a href={`?view=challenge&challenge=${p.id}`}><span>Pay {p.recipient}<span class="mono small run-id">{short(p.id)}</span></span><span>{p.status==='complete'?`${amount(p.result.received)} XLM received`:p.status.replace('_',' ')}</span><span>Open payout</span></a>{/each}</section>{/if}
   {#if loading}<p role="status">Loading saved runs…</p>{:else if !runs.length}<div class="history-empty"><h2>No comparisons yet.</h2><p>Your first live run will appear here with its testnet transaction evidence.</p><a class="button primary" href="?view=lab">Open failure lab</a></div>{:else}<div class="table-wrap"><table><caption class="sr-only">Saved payment recovery comparisons</caption><thead><tr><th>Scenario</th><th>Started</th><th>Status</th><th>Naïve / reconciled payments</th><th><span class="sr-only">Report</span></th></tr></thead><tbody>{#each runs as r}<tr><td><strong>{scenarios.find(s=>s.id===r.scenario)?.name||r.scenario}</strong><span class="mono small run-id">{short(r.id)}</span></td><td>{date(r.created_at)}</td><td><span class="status-label">{r.status}</span></td><td class="mono">{r.clients[0]?.settlements??0} / {r.clients[1]?.settlements??0}</td><td><a class="text-button" href={`?view=lab&run=${r.id}&scenario=${r.scenario}`}>Open report ↗</a></td></tr>{/each}</tbody></table></div>{/if}
  {:else}
   <div class="intro"><div><h1>Put your app<br/>through the same failure.</h1><p>Use your own client and signed testnet transactions.<br/>LedgerDrill changes the connection—not the payment you signed.</p></div></div>
   <div class="integration-layout"><section><h2>Create a proxy session</h2><p>Each session injects its fault once. It forwards supported requests to Stellar’s testnet Horizon endpoint.</p><label for="proxy-scenario">Fault scenario</label><select id="proxy-scenario" name="proxy-scenario" bind:value={scenario}>{#each scenarios as s}<option value={s.id}>{s.name}</option>{/each}</select><button class="button primary" disabled={creatingSession||loading||(authRequired&&!token)} onclick={newSession}>{creatingSession?'Creating session…':'Create proxy session'}</button>
   {#if session}<div class="proxy-result"><label for="proxy-url">Your Horizon base URL</label><input id="proxy-url" name="proxy-url" readonly value={proxyURL} spellcheck="false" autocomplete="off"/><button class="text-button" onclick={()=>copy(proxyURL)}>{copied?'Copied':'Copy URL'}</button><p class="small">Use the testnet network passphrase. If this instance has an access token, send it as a Bearer authorization header.</p><button class="button secondary" disabled={refreshing} onclick={refreshSession}>{refreshing?'Refreshing trace…':'Refresh proxy trace'}</button><p class="mono small">{session.attempts} submission attempts · {session.transactions.filter(t=>t.confirmed&&t.successful).length} successful hashes observed</p>{#if session.events.length}<ol class="timeline">{#each session.events as ev}<li><span class="mono event-time">{time(ev.at)}</span><div><span class="event-kind">{ev.kind}</span><p>{ev.message}</p>{#if ev.hash}<a class="mono hash" href={`https://stellar.expert/explorer/testnet/tx/${ev.hash}`} target="_blank" rel="noreferrer">{short(ev.hash)} ↗</a>{/if}</div></li>{/each}</ol>{/if}</div>{:else}<button class="text-button restore" onclick={refreshSession}>Restore last proxy session</button>{/if}</section>
   <section class="integration-docs"><h2>A small change to your client</h2><p>Replace the Horizon URL in your test configuration. Your app still builds and signs its transactions locally.</p><pre><code>{`// JavaScript · @stellar/stellar-sdk\nimport { Horizon } from '@stellar/stellar-sdk';\n\nconst server = new Horizon.Server(\n  '${proxyURL||'http://127.0.0.1:8098/horizon/SESSION_ID/'}',\n  { allowHttp: true }\n);\n\n// Keep signing for TESTNET.\n// Never generate a new payment simply\n// because the first response timed out.`}</code></pre><h3>Supported in v1</h3><ul><li>Classic transaction submission</li><li>Account reads and account payment/transaction history</li><li>Transaction lookup by hash and fee statistics</li><li>JSON traces at <code>/api/sessions/:id</code></li></ul><h3>What the proxy can observe</h3><p>Submission attempts, upstream responses, injected failures, and transaction hashes. It cannot inspect your application’s database or decide whether a second payment was intentional.</p><p class="small muted">Use a local instance for app integration. The reference demo uses fresh test accounts whose keys stay in memory for that run. It does not collect your wallet keys.</p><a href="https://developers.stellar.org/docs/data/apis/horizon/api-reference/errors/error-handling" target="_blank" rel="noreferrer">Read Stellar’s retry guidance ↗</a></section></div>
  {/if}
 </main>
 <footer><span translate="no">LedgerDrill</span><span>Faults are injected into the connection. Settlements happen on Stellar testnet.</span><a href="https://developers.stellar.org/docs/data/apis/horizon/api-reference/errors/error-handling" target="_blank" rel="noreferrer">Why a timeout isn’t a failed payment ↗</a></footer>
</div>
